func FetchAll(urls []string, fetch func(string) (string, error)) []Result {
	results := make([]Result, len(urls))
	var wg sync.WaitGroup
	for i, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			body, err := fetch(u)
			results[i] = Result{u, body, err}
		}()
	}
	wg.Wait()
	return results
}

type Cache struct {
	mu    sync.RWMutex
	items map[string]entry
}

func (c *Cache) Get(k string) (int, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	e, ok := c.items[k]
	if !ok {
		return 0, false
	}
	if time.Now().After(e.expires) {
		delete(c.items, k) // lazy expiry
		return 0, false
	}
	return e.v, true
}

